//go:build windows

package systray

import (
	_ "embed"

	"golang.org/x/sys/windows"
)

// Official Lucide ChevronRight, generated by build/generate-capture-icons.mjs.
// Keep the icon independent of the menu font and preserve the bundled license.
//
//go:embed assets/chevron-right-light.png
var menuChevronLight []byte

//go:embed assets/chevron-right-dark.png
var menuChevronDark []byte

func loadMenuChevron(dark bool, size int32) (windows.Handle, error) {
	data := menuChevronLight
	if dark {
		data = menuChevronDark
	}
	source, err := pngMenuBitmap(data)
	if err != nil {
		return 0, err
	}
	defer menuDeleteObject.Call(uintptr(source))
	return scaledMenuBitmap(source, size)
}
